fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let gen: i32 = t / 24;
    let flash: i32 = t % 24;
    if flash < 3 {
        host::display::clear(0x2a2a44);
    } else {
        host::display::clear(0x05050d);
    }
    host::display::fill_rect(0, h - 12, w, 12, 0x101018);
    let mut hsh: i32 = gen * 2654435761 + 5;
    hsh = hsh * 1103515245 + 12345;
    let mut px: i32 = w / 4 + ((hsh >> 16) & 32767) % (w / 2);
    let mut py: i32 = 0;
    let mut i: i32 = 0;
    while i < 16 {
        let mut jh: i32 = gen * 7919 + i * 104729;
        jh = jh * 1103515245 + 12345;
        let mut nx: i32 = px + ((jh >> 16) & 63) - 31;
        if nx < 20 { nx = 20; }
        if nx > w - 20 { nx = w - 20; }
        let ny: i32 = py + h / 16;
        host::display::draw_line(px + 2, py, nx + 2, ny, 0x333366);
        host::display::draw_line(px - 2, py, nx - 2, ny, 0x333366);
        host::display::draw_line(px, py, nx, ny, 0xf0f0ff);
        px = nx;
        py = ny;
        i = i + 1;
    }
    host::display::present();
}
